import{_ as l,C as c,o as r,c as n,j as e,a as d,E as o,w as s,al as h}from"./chunks/framework.BawR2jEz.js";const D=JSON.parse('{"title":"Рубрики","description":"Рубрика — тип контента в exDoc, определяющий поля, шаблоны и визуальное представление категорий и документов.","frontmatter":{"title":"Рубрики","description":"Рубрика — тип контента в exDoc, определяющий поля, шаблоны и визуальное представление категорий и документов."},"headers":[],"relativePath":"rubrics/index.md","filePath":"rubrics/index.md"}'),x={name:"rubrics/index.md"};function u(p,a,b,_,m,f){const i=c("FeatureCard"),t=c("FeatureGrid");return r(),n("div",null,[a[0]||(a[0]=e("div",null,[e("h1",{id:"рубрики",tabindex:"-1"},[d("Рубрики "),e("a",{class:"header-anchor",href:"#рубрики","aria-label":'Permalink to "Рубрики"'},"​")]),e("p",null,"Рубрика — это тип контента в exDoc. Она определяет, какие поля имеет контент, как он отображается и какой шаблон страницы используется. Рубрика является центральным элементом системы: категории и документы привязываются к рубрике, получая от неё структуру и визуальное представление."),e("h2",{id:"типы-рубрик",tabindex:"-1"},[d("Типы рубрик "),e("a",{class:"header-anchor",href:"#типы-рубрик","aria-label":'Permalink to "Типы рубрик"'},"​")])],-1)),o(t,null,{default:s(()=>[o(i,{title:"Документ exDoc",details:"Определяет поля и шаблоны для документов: статьи блога, новости, команда, страницы портфолио.",link:"/rubrics/exdoc-document/"}),o(i,{title:"Категория exDoc",details:"Определяет поля и шаблоны для категорий: разделы, рубрики новостей, списки документов.",link:"/rubrics/exdoc-category/"}),o(i,{title:"Коллекция exDoc",details:"Определяет структуру полей для типовых элементов: слайды, карточки отзывов, баннеры.",link:"/rubrics/exdoc-collection/"}),o(i,{title:"Страница OpenCart",details:"Переопределение стандартных шаблонов OpenCart: товар, категория товаров, производитель и тд.",link:"/rubrics/oc-page/"})]),_:1}),a[1]||(a[1]=h('<div><p>Тип рубрики определяет, какие вкладки доступны в форме редактирования и как контент будет обрабатываться системой.</p><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><h3 id="документ-exdoc-—-блог" tabindex="-1">Документ exDoc — Блог <a class="header-anchor" href="#документ-exdoc-—-блог" aria-label="Permalink to &quot;Документ exDoc — Блог&quot;">​</a></h3><p>Вы хотите добавить на сайт раздел «Блог» со статьями.</p><ol><li>Создаёте рубрику <strong>«Блог»</strong> типа <code>Документ exDoc</code> с полями: <code>title</code> (строка), <code>content</code> (текст), <code>image</code> (изображение), <code>author</code> (строка), <code>publish_date</code> (дата)</li><li>Пишете Twig-шаблон документа — разметку отдельной статьи с вызовами <code>{{ fld(&#39;title&#39;) }}</code>, <code>{{ fld(&#39;content&#39;)|raw }}</code> и т.д.</li><li>В админке создаёте документы-статьи, заполняя поля через интерфейс</li><li>Каждая статья получает URL, поля, шаблон и SEO-данные автоматически</li></ol><h3 id="категория-exdoc-—-разделы-блога" tabindex="-1">Категория exDoc — Разделы блога <a class="header-anchor" href="#категория-exdoc-—-разделы-блога" aria-label="Permalink to &quot;Категория exDoc — Разделы блога&quot;">​</a></h3><p>Статьи блога нужно сгруппировать по разделам с отдельной страницей для каждого.</p><ol><li>Создаёте рубрику <strong>«Категории блога»</strong> типа <code>Категория exDoc</code> с полями: <code>description</code> (текст), <code>banner</code> (изображение)</li><li>Пишете Twig-шаблон категории — вызываете <code>getCategoryDocuments()</code> для списка статей и <code>getSubCategories()</code> для дочерних разделов</li><li>Привязываете рубрику документов «Блог» к рубрике категорий — теперь категории знают, с какой рубрикой отображать свои документы</li><li>В админке создаёте категории («Frontend», «Backend»), привязываете к ним статьи — каждая категория получает свою страницу со списком</li></ol><h3 id="коллекция-exdoc-—-слаидер-на-главнои" tabindex="-1">Коллекция exDoc — Слайдер на главной <a class="header-anchor" href="#коллекция-exdoc-—-слаидер-на-главнои" aria-label="Permalink to &quot;Коллекция exDoc — Слайдер на главной&quot;">​</a></h3><p>Нужен слайдер с баннерами, у каждого — своё изображение, заголовок и ссылка.</p><ol><li>Создаёте рубрику <strong>«Слайды»</strong> типа <code>Коллекция exDoc</code> с полями: <code>image</code> (изображение), <code>title</code> (строка), <code>link</code> (строка)</li><li>В блоке «Слайдер» добавляете поле типа <code>exdoc_collection_list</code>, привязанное к рубрике «Слайды»</li><li>Контент-менеджер добавляет слайды через админку, не касаясь кода</li></ol><h3 id="страница-opencart-—-кастомная-страница-товара" tabindex="-1">Страница OpenCart — Кастомная страница товара <a class="header-anchor" href="#страница-opencart-—-кастомная-страница-товара" aria-label="Permalink to &quot;Страница OpenCart — Кастомная страница товара&quot;">​</a></h3><p>Стандартный шаблон страницы товара OpenCart не подходит — нужен свой дизайн.</p><ol><li>Создаёте рубрику типа <code>Страница OpenCart</code> с маршрутом <code>product/product</code></li><li>Добавляете дополнительные поля, которых нет в OpenCart: <code>video_review</code> (YouTube), <code>size_table</code> (таблица)</li><li>Пишете Twig-шаблон — используете свойства товара (<code>name</code>, <code>price</code>, <code>special</code>) и вызываете <code>{{ fld(&#39;video_review&#39;) }}</code> для дополнительных полей</li><li>exDoc перехватывает рендеринг страницы товара и подставляет ваш шаблон вместо стандартного</li></ol><h2 id="создание-рубрики" tabindex="-1">Создание рубрики <a class="header-anchor" href="#создание-рубрики" aria-label="Permalink to &quot;Создание рубрики&quot;">​</a></h2><ol><li>Перейдите в раздел <strong>Рубрики</strong> в левой панели</li><li>Выберите <strong>Тип рубрики</strong> в левой панели</li><li>Нажмите <strong>Добавить</strong></li><li>Заполните настройки — они отличаются в зависимости от типа рубрики</li></ol></div><div><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/exdoc-docs/categories/">Категории</a> — иерархическая структура контента</li><li><a href="/exdoc-docs/documents/">Документы</a> — единицы контента</li><li><a href="/exdoc-docs/fields/">Поля</a> — определение полей рубрики</li><li><a href="/exdoc-docs/templates/">Шаблоны</a> — шаблоны-обёртки страниц (header/footer)</li></ul></div>',2))])}const k=l(x,[["render",u]]);export{D as __pageData,k as default};
